function initAstronomyViz(){const t=document.getElementById("astronomy-viz-bg");if(t)for(let e=0;e<150;e++){const e=document.createElement("div");e.classList.add("star"),e.style.width=3*Math.random()+"px",e.style.height=e.style.width,e.style.left=100*Math.random()+"%",e.style.top=100*Math.random()+"%",e.style.animationDelay=4*Math.random()+"s",t.appendChild(e)}}function initTimeline(){const t=document.getElementById("timeline-container");if(!t)return;[{date:"c. 6th Century BCE",title:"Capital of Avanti",desc:"Ujjain emerges as the capital of the Avanti kingdom, one of the 16 Mahajanapadas."},{date:"c. 3rd Century BCE",title:"Ashoka as Viceroy",desc:"Mauryan Emperor Ashoka serves as the viceroy of Ujjain before ascending to the throne."},{date:"c. 4th Century CE",title:"Gupta Empire Golden Age",desc:"Under Chandragupta II (Vikramaditya), Ujjain becomes a flourishing center of art, literature, and science, home to the Navaratnas including Kalidasa."},{date:"c. 6th-7th Century CE",title:"Center of Astronomy",desc:"Brahmagupta and later Bhaskaracharya (12th C) write foundational treatises on mathematics and astronomy here."},{date:"1235 CE",title:"Invasion by Iltutmish",desc:"The city faces destruction during the Delhi Sultanate invasion, but eventually rebuilds."},{date:"18th Century CE",title:"Maratha Revival",desc:"The Scindia dynasty takes control, restoring temples including the Mahakaleshwar Jyotirlinga, and Jai Singh II builds the Vedh Shala observatory."}].forEach(e=>{const a=document.createElement("div");a.classList.add("timeline-event"),a.innerHTML=`\n            <span class="timeline-date">${e.date}</span>\n            <h3 class="timeline-title">${e.title}</h3>\n            <p class="timeline-desc">${e.desc}</p>\n        `,t.appendChild(a)})}function initMonuments(){const t=document.getElementById("monument-explorer");if(!t)return;[{name:"Mahakaleshwar Jyotirlinga",desc:"One of the 12 Jyotirlingas, a major pilgrimage site rebuilt extensively during the Maratha period."},{name:"Vedh Shala (Jantar Mantar)",desc:"An 18th-century observatory built by Maharaja Jai Singh II to measure time and celestial movements."},{name:"Kalideh Palace",desc:"Situated on an island in the Kshipra river, showing Persian architectural influences from the Mandu Sultans."},{name:"Bhartrihari Caves",desc:"Ancient caves where the stepbrother of King Vikramaditya is said to have meditated."}].forEach(e=>{const a=document.createElement("div");a.classList.add("monument-card"),a.innerHTML=`\n            <h3>${e.name}</h3>\n            <p>${e.desc}</p>\n        `,t.appendChild(a)})}function initTradeMap(){const t=document.getElementById("trade-map-svg");if(!t)return;const e={cities:[{id:"ujjain",name:"Ujjain",x:350,y:250,r:8},{id:"mathura",name:"Mathura",x:350,y:150,r:5},{id:"pataliputra",name:"Pataliputra",x:550,y:180,r:6},{id:"bharuch",name:"Bharuch (Barygaza)",x:200,y:300,r:6},{id:"pratishthana",name:"Pratishthana (Paithan)",x:320,y:380,r:5}],routes:[{from:"ujjain",to:"mathura"},{from:"ujjain",to:"bharuch"},{from:"ujjain",to:"pratishthana"},{from:"mathura",to:"pataliputra"}]};e.routes.forEach(a=>{const n=e.cities.find(t=>t.id===a.from),i=e.cities.find(t=>t.id===a.to);if(n&&i){const e=document.createElementNS("http://www.w3.org/2000/svg","line");e.setAttribute("x1",n.x),e.setAttribute("y1",n.y),e.setAttribute("x2",i.x),e.setAttribute("y2",i.y),e.classList.add("trade-route"),t.appendChild(e)}}),e.cities.forEach(e=>{const a=document.createElementNS("http://www.w3.org/2000/svg","circle");a.setAttribute("cx",e.x),a.setAttribute("cy",e.y),a.setAttribute("r",e.r),a.classList.add("city-node");const n=document.createElementNS("http://www.w3.org/2000/svg","text");n.setAttribute("x",e.x+10),n.setAttribute("y",e.y+4),n.classList.add("city-label"),n.textContent=e.name,t.appendChild(a),t.appendChild(n)})}document.addEventListener("DOMContentLoaded",()=>{initAstronomyViz(),initTimeline(),initMonuments(),initTradeMap()});